using V=arkjson::Value;
void require(bool value,const std::string& reason){if(!value)throw std::runtime_error("SURFACE_QUALITY: "+reason);}
const V& get(const V& v,const char* k){static V nil;const auto* value=v.find(k);return value?*value:nil;}
std::string text(const V& v,const char* k){const auto& value=get(v,k);require(value.t==V::Str&&!value.str.empty()&&value.str.size()<=256,std::string("Expected ")+k);return value.str;}
